L000041	\title{Diagnostic Consistency Tests of the Concordance Cosmology}
L000042	
L000043	
L000044	
L000045	\author{S. M. Koksbang}
L000046	\email{koksbang@cp3.sdu.dk}
L000047	\affiliation{CP$^3$-Origins, University of Southern Denmark, Campusvej 55, DK-5230 Odense M, Denmark}
L000048	\author{A. Heinesen}
L000049	\email{asta.heinesen@nbi.ku.dk}
